/*
 * Tailwind documentation for the Library project.
 * Renders everything from window.TW_DOCS (assets/data.js, generated by
 * generate.js from the project's real Tailwind setup). No dependencies, so it
 * works offline and straight from the file system.
 */
(function () {
  'use strict';

  var DOCS = window.TW_DOCS;
  var main = document.getElementById('d-main');
  var sidebar = document.getElementById('d-sidebar');

  if (!DOCS) {
    main.innerHTML = '<div class="d-page"><h1 class="d-h1">Data not found</h1>' +
      '<p class="d-p">Run <code class="d-inline-code">npm run docs:tailwind</code> in <code class="d-inline-code">frontend/</code> (Node 12.1.0) to create assets/data.js.</p></div>';
    return;
  }

  // ------------------------------------------------------------------ helpers

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  /** Text with `code` spans, escaped. */
  function prose(text) {
    return esc(text).replace(/`([^`]+)`/g, '<code class="d-inline-code">$1</code>');
  }

  /** Syntax-colours a block of CSS declarations. */
  function highlightCss(css) {
    return css.split('\n').map(function (line) {
      var e = esc(line);
      if (/^\s*\/\*/.test(line)) return '<span class="d-com">' + e + '</span>';
      var m = /^(\s*)([-\w]+)(:\s*)(.*?)(;?)$/.exec(line);
      if (m && line.indexOf('{') === -1 && line.indexOf('}') === -1) {
        return esc(m[1]) + '<span class="d-prop">' + esc(m[2]) + '</span>' + esc(m[3]) +
          '<span class="d-val">' + esc(m[4]) + '</span>' + esc(m[5]);
      }
      return e;
    }).join('\n');
  }

  var storage = {
    get: function (k) { try { return localStorage.getItem(k); } catch (e) { return null; } },
    set: function (k, v) { try { localStorage.setItem(k, v); } catch (e) { /* ignore */ } },
  };

  var toastTimer = null;
  function toast(message) {
    var el = document.getElementById('d-toast');
    el.textContent = message;
    el.classList.add('is-shown');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { el.classList.remove('is-shown'); }, 1600);
  }

  function copy(text) {
    var done = function () { toast('Copied ' + text); };
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text).then(done, fallback);
    } else {
      fallback();
    }
    function fallback() {
      var ta = document.createElement('textarea');
      ta.value = text;
      ta.setAttribute('readonly', '');
      ta.style.position = 'fixed';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand('copy'); done(); } catch (e) { toast('Copy failed'); }
      document.body.removeChild(ta);
    }
  }

  function num(n) { return Number(n).toLocaleString('en-US'); }

  // ------------------------------------------------------------------ indexes

  var pagesBySlug = {};
  var syntaxBySlug = {};
  var searchIndex = [];

  DOCS.sections.forEach(function (section) {
    section.pages.forEach(function (page) {
      page.section = section.title;
      pagesBySlug[page.slug] = page;
      searchIndex.push({ kind: 'Page', title: page.title, sub: section.title + ' · ' + page.utilities.length + ' classes', href: '#/u/' + page.slug, key: page.title.toLowerCase() });
      page.utilities.forEach(function (u) {
        var firstLine = u.css.split('\n').filter(function (l) { return l.indexOf('/*') !== 0; })[0] || '';
        searchIndex.push({ kind: 'Class', title: u.c, sub: page.title + ' — ' + firstLine, href: '#/u/' + page.slug + '?c=' + encodeURIComponent(u.c), key: u.c.toLowerCase(), hex: u.hex });
      });
    });
  });
  DOCS.newSyntax.forEach(function (group) {
    syntaxBySlug[group.slug] = group;
    searchIndex.push({ kind: 'Page', title: group.title, sub: 'New syntax', href: '#/syntax/' + group.slug, key: group.title.toLowerCase() });
    group.examples.forEach(function (ex) {
      searchIndex.push({ kind: 'Syntax', title: ex.c, sub: group.title + ' (compiled on demand)', href: '#/syntax/' + group.slug + '?c=' + encodeURIComponent(ex.c), key: ex.c.toLowerCase() });
    });
  });
  DOCS.palette.forEach(function (family) {
    family.shades.forEach(function (s) {
      searchIndex.push({ kind: 'Colour', title: family.name + '-' + s.shade, sub: s.hex + ' · ' + s.oklch, href: '#/colors?c=' + family.name + '-' + s.shade, key: (family.name + '-' + s.shade).toLowerCase(), hex: s.hex });
    });
  });
  [['Overview', '#/'], ['How it works', '#/guide'], ['Colours', '#/colors'], ['Theme scales', '#/theme']].forEach(function (p) {
    searchIndex.push({ kind: 'Page', title: p[0], sub: 'Getting started', href: p[1], key: p[0].toLowerCase() });
  });

  function search(query, limit) {
    var q = query.trim().toLowerCase();
    if (!q) return [];
    var scored = [];
    for (var i = 0; i < searchIndex.length; i++) {
      var item = searchIndex[i];
      var idx = item.key.indexOf(q);
      if (idx === -1) continue;
      var score = item.key === q ? 0 : idx === 0 ? 1 : 2;
      if (item.kind === 'Page') score -= 0.5;
      scored.push({ item: item, score: score, len: item.key.length });
    }
    scored.sort(function (a, b) { return a.score - b.score || a.len - b.len; });
    return scored.slice(0, limit || scored.length).map(function (s) { return s.item; });
  }

  // ------------------------------------------------------------------ sidebar

  var collapsed = {};
  try { collapsed = JSON.parse(storage.get('twdocs-collapsed') || '{}') || {}; } catch (e) { collapsed = {}; }

  function renderSidebar() {
    var groups = [
      { title: 'Getting started', links: [['Overview', '#/'], ['How it works', '#/guide'], ['Colours', '#/colors'], ['Theme scales', '#/theme']] },
      { title: 'New syntax', links: DOCS.newSyntax.map(function (g) { return [g.title, '#/syntax/' + g.slug, g.examples.length]; }) },
    ].concat(DOCS.sections.map(function (s) {
      return { title: s.title, links: s.pages.map(function (p) { return [p.title, '#/u/' + p.slug, p.utilities.length]; }) };
    }));

    sidebar.innerHTML = groups.map(function (g) {
      var isCollapsed = !!collapsed[g.title];
      return '<div class="d-nav-group' + (isCollapsed ? ' is-collapsed' : '') + '" data-group="' + esc(g.title) + '">' +
        '<button class="d-nav-title" type="button" aria-expanded="' + (!isCollapsed) + '">' + esc(g.title) +
        '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button>' +
        '<ul class="d-nav-list">' + g.links.map(function (l) {
          return '<li><a class="d-nav-link" href="' + l[1] + '"><span>' + esc(l[0]) + '</span>' +
            (l[2] !== undefined ? '<span class="d-nav-count">' + l[2] + '</span>' : '') + '</a></li>';
        }).join('') + '</ul></div>';
    }).join('');
  }

  sidebar.addEventListener('click', function (e) {
    var btn = e.target.closest('.d-nav-title');
    if (btn) {
      var group = btn.parentNode;
      group.classList.toggle('is-collapsed');
      var isCollapsed = group.classList.contains('is-collapsed');
      btn.setAttribute('aria-expanded', String(!isCollapsed));
      collapsed[group.getAttribute('data-group')] = isCollapsed;
      storage.set('twdocs-collapsed', JSON.stringify(collapsed));
      return;
    }
    if (e.target.closest('.d-nav-link')) closeMenu();
  });

  function markActive() {
    var hash = location.hash.split('?')[0] || '#/';
    var active = null;
    Array.prototype.forEach.call(sidebar.querySelectorAll('.d-nav-link'), function (a) {
      var isActive = a.getAttribute('href') === hash;
      a.classList.toggle('is-active', isActive);
      if (isActive) { a.setAttribute('aria-current', 'page'); active = a; } else { a.removeAttribute('aria-current'); }
    });
    if (active) {
      var group = active.closest('.d-nav-group');
      if (group && group.classList.contains('is-collapsed')) group.classList.remove('is-collapsed');
      // Scroll the sidebar alone (scrollIntoView would move the page too), and
      // only when the link is actually outside it.
      var r = active.getBoundingClientRect();
      var sr = sidebar.getBoundingClientRect();
      if (sr.height > 0 && (r.top < sr.top || r.bottom > sr.bottom)) {
        sidebar.scrollTop += (r.top - sr.top) - sr.height / 2;
      }
    }
  }

  // Mobile menu
  var menuBtn = document.getElementById('d-menu-btn');
  var scrim = document.getElementById('d-scrim');
  function closeMenu() {
    sidebar.classList.remove('is-open');
    scrim.hidden = true;
    menuBtn.setAttribute('aria-expanded', 'false');
  }
  menuBtn.addEventListener('click', function () {
    var open = !sidebar.classList.contains('is-open');
    sidebar.classList.toggle('is-open', open);
    scrim.hidden = !open;
    menuBtn.setAttribute('aria-expanded', String(open));
  });
  scrim.addEventListener('click', closeMenu);

  // Theme toggle
  document.getElementById('d-theme-btn').addEventListener('click', function () {
    var root = document.documentElement;
    var current = root.getAttribute('data-theme') ||
      (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
    var next = current === 'dark' ? 'light' : 'dark';
    root.setAttribute('data-theme', next);
    storage.set('twdocs-theme', next);
  });

  // ------------------------------------------------------------------ previews

  /** Markup for a live preview of `cls`, rendered by the project's own CSS. */
  function preview(kind, cls, util) {
    var c = esc(cls);
    switch (kind) {
      case 'color':
        return util && util.hex
          ? '<div class="d-swatch-cell"><span class="d-swatch"><span style="background:' + esc(util.hex) + '"></span></span><span class="d-hex">' + esc(util.hex) + '</span></div>'
          : '';
      case 'swatch':
        return '<div class="d-preview"><div class="d-pv-box ' + c + '"></div></div>';
      case 'text':
        return '<div class="d-preview"><span class="d-pv-text ' + c + '">The quick brown fox</span></div>';
      case 'radius':
      case 'opacity':
      case 'box':
      case 'size':
        return '<div class="d-preview"><div class="d-pv-box ' + c + '"></div></div>';
      case 'border':
        return '<div class="d-preview"><div class="d-pv-border ' + c + '"></div></div>';
      case 'shadow':
      case 'ring':
        return '<div class="d-preview"><div class="d-pv-box-light ' + c + '"></div></div>';
      case 'transform':
        return '<div class="d-preview"><div class="d-pv-box d-pv-arrow ' + c + '">&rarr;</div></div>';
      case 'animate':
        return '<div class="d-preview"><div class="d-pv-box ' + c + '" style="width:28px;height:28px"></div></div>';
      case 'padding':
        return '<div class="d-preview"><div class="d-pv-frame ' + c + '"><div class="d-pv-inner"></div></div></div>';
      case 'margin':
        return '<div class="d-preview"><div class="d-pv-frame"><div class="d-pv-inner ' + c + '"></div></div></div>';
      case 'width':
        return '<div class="d-preview"><div style="width:100%;overflow:hidden"><div class="d-pv-fill ' + c + '"></div></div></div>';
      case 'gradient':
        return '<div class="d-preview"><div class="d-pv-wide ' + c + ' from-sky-400 to-violet-500"></div></div>';
      default:
        return '';
    }
  }

  // ------------------------------------------------------------------ pages

  function pageShell(inner) { return '<article class="d-page">' + inner + '</article>'; }

  function renderHome() {
    var m = DOCS.meta;
    var generated = new Date(m.generated);
    return pageShell(
      '<p class="d-eyebrow">Library project · frontend</p>' +
      '<h1 class="d-h1">Tailwind CSS in this project</h1>' +
      '<p class="d-lead">Every class the Library frontend can use, with the exact CSS it produces — generated from the project\'s real ' +
      '<code class="d-inline-code">tailwind.config.js</code>, palette and on-demand compiler, not copied from the Tailwind website.</p>' +

      '<div class="d-cards">' +
        card(num(m.totalUtilities), 'utility classes in the stylesheet') +
        card(num(m.addedUtilities), 'added by this project on top of Tailwind 1.9') +
        card(num(m.colors), 'colours in the Tailwind 4 palette') +
        card(num(m.pages), 'reference pages') +
        card(m.tailwindVersion, 'Tailwind engine installed') +
      '</div>' +

      '<h2 class="d-h2">How the pieces fit</h2>' +
      '<p class="d-p">The installed Tailwind is ' + esc(m.tailwindVersion) + ' and cannot be upgraded offline (Tailwind 2+ also needs Node 12.13+). ' +
      'Three pieces let the code use current Tailwind class names anyway:</p>' +
      flow() +
      '<p class="d-p">Read <a href="#/guide">How it works</a> for the details, or jump straight in:</p>' +

      '<div class="d-links">' +
        linkCard('#/colors', 'Colours', 'The Tailwind 4 palette, with each shade\'s OKLCH source and hex value.') +
        linkCard('#/syntax/arbitrary-values', 'Arbitrary values', '`w-[250px]`, `grid-cols-[1fr_2fr]`, `bg-[#1da1f2]` — compiled on demand.') +
        linkCard('#/syntax/opacity-modifiers', 'Opacity modifiers', '`bg-black/50`, `text-rose-600/75`, `bg-sky-500/[.35]`.') +
        linkCard('#/syntax/variants', 'Variants', '`2xl:`, `dark:`, `aria-*`, `data-[…]`, `[&>*]:`, `group-*` on any utility.') +
        linkCard('#/u/background-color', 'Background Color', 'Start of the utility reference, one page per CSS feature.') +
        linkCard('#/theme', 'Theme scales', 'Spacing, breakpoints, type scale, radii, shadows and more.') +
      '</div>' +

      '<h2 class="d-h2">Rules of thumb</h2>' +
      '<ul class="d-list">' +
        '<li><strong>Write class names out in full.</strong> The production purge and the compiler find classes by reading the source, so ' +
          '<code class="d-inline-code">`bg-${color}-500`</code> produces nothing. Use <code class="d-inline-code">isRed ? \'bg-red-500\' : \'bg-blue-500\'</code>.</li>' +
        '<li><strong>Transforms need no <code class="d-inline-code">transform</code> class</strong> — <code class="d-inline-code">rotate-45</code> works on its own, as in Tailwind 3.</li>' +
        '<li><strong>Colours are Tailwind 4\'s</strong> (<code class="d-inline-code">blue-500</code> is <code class="d-inline-code">#2b7fff</code>), including the new ' +
          '<code class="d-inline-code">mauve</code>, <code class="d-inline-code">olive</code>, <code class="d-inline-code">mist</code> and <code class="d-inline-code">taupe</code>.</li>' +
        '<li><strong>Not supported:</strong> container queries (<code class="d-inline-code">@container</code>, <code class="d-inline-code">@md:</code>), and opacity modifiers on non-hex colours.</li>' +
      '</ul>' +
      '<p class="d-p d-muted" style="font-size:13px">Generated ' + esc(generated.toLocaleString()) + ' from the frontend in this repository. ' +
      'Regenerate with <code class="d-inline-code">npm run docs:tailwind</code> in <code class="d-inline-code">frontend/</code> after changing the Tailwind config, palette or compiler.</p>'
    );
  }

  function card(n, label) {
    return '<div class="d-card"><div class="d-card-num">' + esc(n) + '</div><div class="d-card-label">' + esc(label) + '</div></div>';
  }
  function linkCard(href, title, text) {
    return '<a class="d-link-card" href="' + href + '"><strong>' + esc(title) + '</strong><span>' + prose(text) + '</span></a>';
  }
  function flow() {
    return '<div class="d-flow">' +
      '<div class="d-flow-step"><span class="d-flow-file">frontend/tailwind.config.js</span><h4>Backfilled config</h4>' +
        '<p>Adds Tailwind 2/3 utilities to 1.9 and replaces its shadow, gradient and transform plugins with Tailwind 3 behaviour. Purges unused classes in production.</p></div>' +
      '<div class="d-flow-step"><span class="d-flow-file">frontend/tailwind.palette.js</span><h4>Tailwind 4 palette</h4>' +
        '<p>Tailwind 4.3.3\'s OKLCH colours, converted to hex (1.9\'s opacity utilities need rgba channels).</p></div>' +
      '<div class="d-flow-step"><span class="d-flow-file">frontend/scripts/tailwind-jit.js</span><h4>On-demand compiler</h4>' +
        '<p>Scans <code class="d-inline-code">src/</code> and compiles what no config can: arbitrary values, opacity modifiers, newer variants. Writes <code class="d-inline-code">src/tailwind-jit.css</code>.</p></div>' +
      '</div>';
  }

  function renderGuide() {
    var cv = DOCS.compilerVariants;
    function chips(list) { return list.map(function (v) { return '<code class="d-inline-code">' + esc(v) + ':</code>'; }).join(' '); }
    return pageShell(
      '<p class="d-eyebrow">Getting started</p><h1 class="d-h1">How it works</h1>' +
      '<p class="d-lead">The frontend is built with Create React App 4 and Tailwind 1.9.6. The project runs offline on Node 12.1.0, so newer Tailwind cannot be installed — instead the missing behaviour is added in three layers.</p>' +
      flow() +

      '<h2 class="d-h2">1. The config: Tailwind 1.9, extended</h2>' +
      '<p class="d-p"><code class="d-inline-code">tailwind.config.js</code> is processed by Tailwind 1.9 itself, into <code class="d-inline-code">src/index.css</code>. It:</p>' +
      '<ul class="d-list">' +
        '<li>backfills Tailwind 2/3 utilities: half-step spacing, the spacing scale for <code class="d-inline-code">top/right/bottom/left</code>, <code class="d-inline-code">min-h-*</code>/<code class="d-inline-code">max-h-*</code>, <code class="d-inline-code">w-fit</code>, <code class="d-inline-code">h-dvh</code>, <code class="d-inline-code">max-w-7xl</code>, <code class="d-inline-code">text-9xl</code>, <code class="d-inline-code">line-clamp-*</code>, <code class="d-inline-code">border-x/y/s/e</code>, logical <code class="d-inline-code">rounded-s/e</code>, <code class="d-inline-code">overflow-clip</code>, <code class="d-inline-code">whitespace-nowrap</code>;</li>' +
        '<li>adds Tailwind 2\'s <a href="#/u/ring-width">ring utilities</a>;</li>' +
        '<li>replaces four core plugins whose Tailwind 3 behaviour cannot be layered on: <a href="#/u/box-shadow">box shadows</a> compose with rings and take <a href="#/u/box-shadow-color">shadow colours</a>; <a href="#/u/gradient-color-stops">gradient stops</a> take positions; <a href="#/u/rotate">rotate</a>, <a href="#/u/scale">scale</a>, <a href="#/u/translate">translate</a> and <a href="#/u/skew">skew</a> apply the transform themselves;</li>' +
        '<li>replaces the palette with <a href="#/colors">Tailwind 4\'s</a>, and sets Tailwind 3\'s defaults for border colour (<code class="d-inline-code">gray-200</code>) and placeholder colour (<code class="d-inline-code">gray-400</code>);</li>' +
        '<li>enables <code class="d-inline-code">disabled:</code>, <code class="d-inline-code">first:</code>/<code class="d-inline-code">last:</code>, <code class="d-inline-code">group-hover:</code> and <code class="d-inline-code">focus:</code> where the components use them.</li>' +
      '</ul>' +
      '<p class="d-p">Production builds purge every utility not found in <code class="d-inline-code">src/</code> or <code class="d-inline-code">public/index.html</code>: the stylesheet shrinks from about 2.8 MB to about 6 KB gzipped.</p>' +

      '<h2 class="d-h2">2. The palette</h2>' +
      '<p class="d-p"><code class="d-inline-code">tailwind.palette.js</code> keeps Tailwind 4.3.3\'s colours exactly as published (OKLCH) and converts them to sRGB hex when the config loads, using CSS Color 4 gamut mapping for the few shades wider than sRGB. Checked against the browser\'s own conversion: 274 of 286 colours identical, the rest within 1/255. See <a href="#/colors">Colours</a>.</p>' +

      '<h2 class="d-h2">3. The on-demand compiler</h2>' +
      '<p class="d-p"><code class="d-inline-code">scripts/tailwind-jit.js</code> reads every file in <code class="d-inline-code">src/</code>, finds the class names, and writes CSS for each one it recognises to <code class="d-inline-code">src/tailwind-jit.css</code>, imported after <code class="d-inline-code">index.css</code>. It runs before <code class="d-inline-code">npm start</code>, <code class="d-inline-code">npm run build</code> and <code class="d-inline-code">npm test</code>, and keeps watching while the dev server runs.</p>' +
      '<p class="d-p">It emits every class the source uses — including ones 1.9 already generates — sorted in Tailwind\'s cascade order: media conditions (screen sizes last), then variants, then utility order taken from 1.9\'s own output. That is what lets plain and new-syntax classes on one element behave as in Tailwind 3, e.g. <code class="d-inline-code">bg-[#123] bg-opacity-50</code> or <code class="d-inline-code">p-[3px] px-[5px]</code>. <code class="d-inline-code">npm run test:tailwind</code> runs its 126 tests.</p>' +

      '<h3 class="d-h3">Variants the compiler understands (on any utility)</h3>' +
      '<p class="d-p"><strong>Screens:</strong> ' + chips(cv.screens) + '</p>' +
      '<p class="d-p"><strong>Media:</strong> ' + chips(cv.media) + '</p>' +
      '<p class="d-p"><strong>States:</strong> ' + chips(cv.states) + '</p>' +
      '<p class="d-p"><strong>Pseudo-elements:</strong> ' + chips(cv.pseudoElements) + '</p>' +
      '<p class="d-p"><strong>Attributes:</strong> ' + chips(cv.attributes) + '</p>' +
      '<p class="d-p"><strong>Relational:</strong> ' + chips(cv.relational) + '</p>' +
      '<p class="d-p"><strong>Other:</strong> ' + cv.other.map(function (v) { return '<code class="d-inline-code">' + esc(v) + '</code>'; }).join(' ') + '</p>' +
      '<p class="d-p">Examples with their compiled CSS are on the <a href="#/syntax/variants">Variants</a> page. Each utility page also lists the variants Tailwind 1.9 already puts in <code class="d-inline-code">index.css</code> for it.</p>' +

      '<h2 class="d-h2">Rules and limits</h2>' +
      '<ul class="d-list">' +
        '<li><strong>Write class names out in full.</strong> Both the purge and the compiler find classes by reading source text; a name assembled at runtime is invisible to them.</li>' +
        '<li><strong>Container queries</strong> (<code class="d-inline-code">@container</code>, <code class="d-inline-code">@md:</code>) are not supported.</li>' +
        '<li><strong>Opacity modifiers</strong> (<code class="d-inline-code">/50</code>) work on hex colours only — every palette colour is hex.</li>' +
        '<li><strong>Existing colour names use Tailwind 4 shades</strong>, so designs copied from Tailwind 1.9-era docs will look slightly more saturated.</li>' +
      '</ul>' +

      '<h2 class="d-h2">Keeping these docs current</h2>' +
      '<p class="d-p">Everything here is generated from the frontend. After changing <code class="d-inline-code">tailwind.config.js</code>, <code class="d-inline-code">tailwind.palette.js</code> or the compiler, regenerate with Node 12.1.0:</p>' +
      '<pre class="d-code"><code>cd frontend\nnpm run docs:tailwind</code></pre>'
    );
  }

  function renderColors(focus) {
    var shades = DOCS.palette[0].shades.map(function (s) { return s.shade; });
    var head = '<div class="d-palette-row" aria-hidden="true"><span></span>' +
      shades.map(function (s) { return '<span class="d-palette-head">' + s + '</span>'; }).join('') + '</div>';
    var rows = DOCS.palette.map(function (f) {
      return '<div class="d-palette-row"><span class="d-palette-name">' + esc(f.name) + '</span>' +
        f.shades.map(function (s) {
          var name = f.name + '-' + s.shade;
          return '<button type="button" class="d-chip" style="background:' + esc(s.hex) + '" data-color="' + esc(name) + '" ' +
            'title="' + esc(name + ' ' + s.hex) + '" aria-label="' + esc(name + ', ' + s.hex) + '"></button>';
        }).join('') + '</div>';
    }).join('');

    var table = DOCS.palette.map(function (f) {
      return f.shades.map(function (s) {
        var name = f.name + '-' + s.shade;
        return '<tr id="color-' + esc(name) + '"><td><div class="d-swatch-cell"><span class="d-swatch"><span style="background:' + esc(s.hex) + '"></span></span>' +
          '<button type="button" class="d-class" data-copy="' + esc(name) + '">' + esc(name) + '</button></div></td>' +
          '<td><code class="d-hex">' + esc(s.hex) + '</code></td><td><code class="d-hex">' + esc(s.oklch) + '</code></td></tr>';
      }).join('');
    }).join('');

    return pageShell(
      '<p class="d-eyebrow">Getting started</p><h1 class="d-h1">Colours</h1>' +
      '<p class="d-lead">Tailwind 4.3.3\'s palette: ' + DOCS.palette.length + ' families × 11 shades. Every colour utility accepts these names — ' +
      '<code class="d-inline-code">bg-sky-500</code>, <code class="d-inline-code">text-rose-600</code>, <code class="d-inline-code">ring-violet-400</code> — plus ' +
      '<code class="d-inline-code">black</code>, <code class="d-inline-code">white</code>, <code class="d-inline-code">transparent</code> and <code class="d-inline-code">current</code>.</p>' +
      '<div class="d-note"><span><strong>Hex, from OKLCH.</strong> Tailwind 4 defines colours in OKLCH; Tailwind 1.9\'s opacity utilities need rgba channels, so each value is converted to sRGB hex. Click a swatch to copy its name.</span></div>' +
      '<div class="d-palette" id="d-palette">' + head + rows + '</div>' +
      '<div class="d-chip-detail" id="d-chip-detail"></div>' +
      '<h2 class="d-h2">All values</h2>' +
      '<div class="d-table-wrap"><div class="d-table-scroll"><table class="d-table"><thead><tr><th>Name</th><th>Hex</th><th>OKLCH source (Tailwind 4.3.3)</th></tr></thead>' +
      '<tbody>' + table + '</tbody></table></div></div>'
    );
  }

  function colorDetail(name) {
    var parts = name.split('-');
    var shade = parts.pop();
    var fam = parts.join('-');
    var family = DOCS.palette.filter(function (f) { return f.name === fam; })[0];
    if (!family) return '';
    var s = family.shades.filter(function (x) { return x.shade === shade; })[0];
    if (!s) return '';
    var uses = ['bg', 'text', 'border', 'ring', 'from', 'to', 'shadow', 'divide', 'placeholder'].map(function (p) {
      return '<button type="button" class="d-class" data-copy="' + esc(p + '-' + name) + '">' + esc(p + '-' + name) + '</button>';
    }).join(' &nbsp; ');
    return '<div class="d-example"><div class="d-example-head"><strong style="text-transform:capitalize">' + esc(fam + ' ' + shade) + '</strong>' +
      '<span class="d-hex">' + esc(s.hex) + ' · ' + esc(s.oklch) + '</span></div>' +
      '<div style="display:flex;gap:16px;align-items:center;padding:14px;flex-wrap:wrap">' +
      '<span class="d-swatch" style="width:56px;height:56px"><span style="background:' + esc(s.hex) + '"></span></span>' +
      '<div style="flex:1;min-width:220px;line-height:2">' + uses + '</div></div></div>';
  }

  function renderTheme() {
    var t = DOCS.theme;
    function rows(obj, render) { return Object.keys(obj).map(function (k) { return render(k, obj[k]); }).join(''); }
    function remToPx(v) {
      var m = /^(-?[\d.]+)(rem|px)$/.exec(String(v));
      if (!m) return null;
      return m[2] === 'rem' ? parseFloat(m[1]) * 16 : parseFloat(m[1]);
    }
    function table(head, body) {
      return '<div class="d-table-wrap"><div class="d-table-scroll" style="max-height:none"><table class="d-table"><thead><tr>' +
        head.map(function (h) { return '<th>' + h + '</th>'; }).join('') + '</tr></thead><tbody>' + body + '</tbody></table></div></div>';
    }
    function keyCell(k) { return '<td><code class="d-inline-code">' + esc(k) + '</code></td>'; }
    function valCell(v) { return '<td><code class="d-hex">' + esc(Array.isArray(v) ? v.join(', ') : v) + '</code></td>'; }

    var maxScreen = 1600;
    return pageShell(
      '<p class="d-eyebrow">Getting started</p><h1 class="d-h1">Theme scales</h1>' +
      '<p class="d-lead">The resolved theme values behind the utilities — Tailwind 1.9\'s defaults plus this project\'s extensions.</p>' +

      '<h2 class="d-h2" id="screens">Breakpoints</h2>' +
      '<p class="d-p">Mobile-first: <code class="d-inline-code">md:flex</code> applies from 768px up. <code class="d-inline-code">2xl:</code> exists only through the compiler.</p>' +
      table(['Prefix', 'Min width', ''], rows(t.screens, function (k, v) {
        var px = parseFloat(v) || 0;
        return '<tr>' + keyCell(k + ':') + valCell(v) + '<td style="width:50%"><div class="d-screen-bar" style="width:' + Math.min(100, px / maxScreen * 100) + '%"></div></td></tr>';
      })) +

      '<h2 class="d-h2" id="spacing">Spacing</h2>' +
      '<p class="d-p">Used by padding, margin, width, height, gap, inset, space-between, min/max sizes and translate.</p>' +
      table(['Key', 'Value', 'Pixels', ''], rows(t.spacing, function (k, v) {
        var px = remToPx(v);
        return '<tr>' + keyCell(k) + valCell(v) + '<td class="d-hex">' + (px === null ? '—' : px + 'px') + '</td>' +
          '<td style="width:45%">' + (px === null ? '' : '<div class="d-scale-bar" style="width:' + Math.min(px, 320) + 'px;max-width:100%"></div>') + '</td></tr>';
      })) +

      '<h2 class="d-h2" id="font-size">Font size</h2>' +
      table(['Class', 'Size', 'Sample'], rows(t.fontSize, function (k, v) {
        var size = Array.isArray(v) ? v[0] : v;
        return '<tr>' + keyCell('text-' + k) + valCell(size) + '<td><span style="font-size:' + esc(size) + ';line-height:1.1;white-space:nowrap">Aa</span></td></tr>';
      })) +

      '<h2 class="d-h2" id="font-weight">Font weight</h2>' +
      table(['Class', 'Weight', 'Sample'], rows(t.fontWeight, function (k, v) {
        return '<tr>' + keyCell('font-' + k) + valCell(v) + '<td><span style="font-weight:' + esc(v) + '">The quick brown fox</span></td></tr>';
      })) +

      '<h2 class="d-h2" id="font-family">Font family</h2>' +
      table(['Class', 'Stack'], rows(t.fontFamily, function (k, v) { return '<tr>' + keyCell('font-' + k) + valCell(v) + '</tr>'; })) +

      '<h2 class="d-h2" id="line-height">Line height &amp; letter spacing</h2>' +
      table(['Class', 'Value'], rows(t.lineHeight, function (k, v) { return '<tr>' + keyCell('leading-' + k) + valCell(v) + '</tr>'; }) +
        rows(t.letterSpacing, function (k, v) { return '<tr>' + keyCell('tracking-' + k) + valCell(v) + '</tr>'; })) +

      '<h2 class="d-h2" id="radius">Border radius</h2>' +
      table(['Class', 'Value', ''], rows(t.borderRadius, function (k, v) {
        var cls = k === 'default' ? 'rounded' : 'rounded-' + k;
        return '<tr>' + keyCell(cls) + valCell(v) + '<td><div style="width:48px;height:48px;background:var(--accent);border-radius:' + esc(v) + '"></div></td></tr>';
      })) +

      '<h2 class="d-h2" id="shadow">Box shadow</h2>' +
      table(['Class', 'Value', ''], rows(t.boxShadow, function (k, v) {
        var cls = k === 'default' ? 'shadow' : 'shadow-' + k;
        return '<tr>' + keyCell(cls) + valCell(v) + '<td><div class="d-preview" style="min-height:0;padding:14px"><div style="width:48px;height:48px;background:#fff;border-radius:8px;box-shadow:' + esc(v) + '"></div></div></td></tr>';
      })) +

      '<h2 class="d-h2" id="opacity">Opacity</h2>' +
      table(['Key', 'Value', ''], rows(t.opacity, function (k, v) {
        return '<tr>' + keyCell(k) + valCell(v) + '<td><div style="width:48px;height:24px;border-radius:5px;background:var(--accent);opacity:' + esc(v) + '"></div></td></tr>';
      })) +

      '<h2 class="d-h2" id="borders">Border, ring and offset widths</h2>' +
      table(['Class', 'Value'], rows(t.borderWidth, function (k, v) { return '<tr>' + keyCell(k === 'default' ? 'border' : 'border-' + k) + valCell(v) + '</tr>'; }) +
        rows(t.ringWidth, function (k, v) { return '<tr>' + keyCell(k === 'DEFAULT' ? 'ring' : 'ring-' + k) + valCell(v) + '</tr>'; }) +
        rows(t.ringOffsetWidth, function (k, v) { return '<tr>' + keyCell('ring-offset-' + k) + valCell(v) + '</tr>'; })) +

      '<h2 class="d-h2" id="z">Z-index &amp; durations</h2>' +
      table(['Class', 'Value'], rows(t.zIndex, function (k, v) { return '<tr>' + keyCell('z-' + k) + valCell(v) + '</tr>'; }) +
        rows(t.transitionDuration, function (k, v) { return '<tr>' + keyCell('duration-' + k) + valCell(v) + '</tr>'; }))
    );
  }

  function renderSyntax(group, focus) {
    var cards = group.examples.map(function (ex) {
      var pv = ex.preview ? preview(ex.preview, ex.c) : '';
      return '<div class="d-example" id="ex-' + esc(ex.c) + '">' +
        '<div class="d-example-head"><button type="button" class="d-class" data-copy="' + esc(ex.c) + '">' + esc(ex.c) + '</button>' +
        '<span class="d-pill d-pill-accent">compiled on demand</span></div>' +
        '<div class="d-example-body' + (pv ? '' : ' no-preview') + '">' +
        '<pre class="d-code"><button type="button" class="d-copy" data-copy-code>Copy</button><code>' + highlightCss(ex.css) + '</code></pre>' +
        (pv ? '<div class="d-example-preview">' + pv + '</div>' : '') +
        '</div></div>';
    }).join('');
    return pageShell(
      '<p class="d-eyebrow">New syntax</p><h1 class="d-h1">' + esc(group.title) + '</h1>' +
      '<p class="d-lead">' + prose(group.intro) + '</p>' +
      '<div class="d-meta"><span class="d-pill">' + group.examples.length + ' examples</span>' +
      '<span class="d-pill d-pill-accent">CSS below is the compiler\'s actual output</span></div>' +
      '<div class="d-examples">' + cards + '</div>'
    );
  }

  function renderUtilityPage(page, focus) {
    var added = page.utilities.filter(function (u) { return u.n; }).length;
    var hasPreview = !!page.preview;
    var meta = '<div class="d-meta">' +
      '<span class="d-pill">' + num(page.utilities.length) + ' classes</span>' +
      (added ? '<span class="d-pill d-pill-new">' + (added === page.utilities.length ? 'All' : num(added)) + ' added by this project</span>' : '') +
      '<span class="d-pill">In index.css: ' + (page.variants.length ? esc(page.variants.join(', ')) : 'no variants') + '</span>' +
      '<span class="d-pill d-pill-accent">Any variant via the compiler</span></div>';

    return pageShell(
      '<p class="d-eyebrow">' + esc(page.section) + '</p><h1 class="d-h1">' + esc(page.title) + '</h1>' +
      '<p class="d-lead">' + prose(page.description) + '</p>' + meta +
      '<div class="d-toolbar"><input class="d-filter" id="d-filter" type="search" placeholder="Filter ' + esc(page.title.toLowerCase()) + ' classes…" aria-label="Filter classes">' +
      '<span class="d-count" id="d-count"></span></div>' +
      '<div class="d-table-wrap"><div class="d-table-scroll" id="d-table-scroll"><table class="d-table">' +
      '<thead><tr><th class="d-td-class">Class</th><th>Properties</th>' + (hasPreview ? '<th class="d-td-preview">Preview</th>' : '') + '</tr></thead>' +
      '<tbody id="d-rows"></tbody></table></div></div>'
    );
  }

  function utilityRows(page, filter) {
    var f = (filter || '').trim().toLowerCase();
    var list = f ? page.utilities.filter(function (u) { return u.c.toLowerCase().indexOf(f) !== -1 || u.css.toLowerCase().indexOf(f) !== -1; }) : page.utilities;
    var html = list.map(function (u) {
      return '<tr id="u-' + esc(u.c) + '"><td class="d-td-class"><button type="button" class="d-class" data-copy="' + esc(u.c) + '">' + esc(u.c) +
        (u.n ? '<span class="d-new" title="Not in stock Tailwind 1.9">new</span>' : '') + '</button></td>' +
        '<td><pre class="d-css">' + highlightCss(u.css) + '</pre></td>' +
        (page.preview ? '<td class="d-td-preview">' + preview(page.preview, u.c, u) + '</td>' : '') + '</tr>';
    }).join('');
    return { html: html || '<tr><td colspan="3" class="d-empty">No classes match “' + esc(filter) + '”.</td></tr>', count: list.length };
  }

  function renderSearchPage(query) {
    var results = search(query);
    var groups = {};
    results.forEach(function (r) { (groups[r.kind] = groups[r.kind] || []).push(r); });
    var order = ['Page', 'Class', 'Syntax', 'Colour'];
    var body = results.length ? order.filter(function (k) { return groups[k]; }).map(function (k) {
      var list = groups[k];
      return '<h2 class="d-h2">' + k + (list.length > 1 ? (k === 'Class' ? 'es' : 's') : '') + ' <span class="d-count">' + num(list.length) + '</span></h2>' +
        '<div class="d-table-wrap"><div class="d-table-scroll"><table class="d-table"><tbody>' +
        list.slice(0, 400).map(function (r) {
          return '<tr><td class="d-td-class"><a class="d-class" href="' + r.href + '">' + esc(r.title) + '</a></td><td class="d-muted" style="font-size:13px">' + esc(r.sub) + '</td></tr>';
        }).join('') + '</tbody></table></div></div>' +
        (list.length > 400 ? '<p class="d-p d-muted">Showing the first 400 — refine the search to see more.</p>' : '');
    }).join('') : '<p class="d-p">Nothing matches “' + esc(query) + '”. Classes like <code class="d-inline-code">w-[250px]</code> or <code class="d-inline-code">bg-black/50</code> are compiled on demand — see <a href="#/syntax/arbitrary-values">Arbitrary values</a>.</p>';
    return pageShell('<p class="d-eyebrow">Search</p><h1 class="d-h1">Results for “' + esc(query) + '”</h1>' +
      '<p class="d-lead">' + num(results.length) + ' matches across classes, pages, examples and colours.</p>' + body);
  }

  function renderNotFound() {
    return pageShell('<h1 class="d-h1">Page not found</h1><p class="d-p"><a href="#/">Back to the overview</a></p>');
  }

  // ------------------------------------------------------------------ router

  function parseHash() {
    var raw = location.hash.replace(/^#/, '') || '/';
    var qIndex = raw.indexOf('?');
    var path = qIndex === -1 ? raw : raw.slice(0, qIndex);
    var params = {};
    if (qIndex !== -1) {
      raw.slice(qIndex + 1).split('&').forEach(function (pair) {
        var kv = pair.split('=');
        params[decodeURIComponent(kv[0])] = decodeURIComponent((kv[1] || '').replace(/\+/g, ' '));
      });
    }
    return { path: path, params: params };
  }

  var titleBase = 'Tailwind CSS — Library Project Docs';

  function route() {
    var r = parseHash();
    var parts = r.path.split('/').filter(Boolean);
    var title = titleBase;
    var after = null;

    if (parts.length === 0) {
      main.innerHTML = renderHome();
    } else if (parts[0] === 'guide') {
      main.innerHTML = renderGuide();
      title = 'How it works — ' + titleBase;
    } else if (parts[0] === 'colors') {
      main.innerHTML = renderColors();
      title = 'Colours — ' + titleBase;
      after = function () {
        if (r.params.c) {
          document.getElementById('d-chip-detail').innerHTML = colorDetail(r.params.c);
          focusRow(document.getElementById('color-' + r.params.c));
        }
      };
    } else if (parts[0] === 'theme') {
      main.innerHTML = renderTheme();
      title = 'Theme scales — ' + titleBase;
    } else if (parts[0] === 'syntax' && syntaxBySlug[parts[1]]) {
      var group = syntaxBySlug[parts[1]];
      main.innerHTML = renderSyntax(group);
      title = group.title + ' — ' + titleBase;
      after = function () {
        if (r.params.c) {
          var card = document.getElementById('ex-' + r.params.c);
          if (card) { card.style.boxShadow = '0 0 0 2px var(--accent)'; card.scrollIntoView({ block: 'center' }); }
        }
      };
    } else if (parts[0] === 'u' && pagesBySlug[parts[1]]) {
      var page = pagesBySlug[parts[1]];
      main.innerHTML = renderUtilityPage(page);
      title = page.title + ' — ' + titleBase;
      after = function () { mountUtilityTable(page, r.params.c); };
    } else if (parts[0] === 'search') {
      main.innerHTML = renderSearchPage(r.params.q || '');
      title = 'Search — ' + titleBase;
    } else {
      main.innerHTML = renderNotFound();
    }

    document.title = title;
    markActive();
    window.scrollTo(0, 0);
    if (after) after();
  }

  function mountUtilityTable(page, focusClass) {
    var rowsEl = document.getElementById('d-rows');
    var countEl = document.getElementById('d-count');
    var filterEl = document.getElementById('d-filter');
    function draw() {
      var out = utilityRows(page, filterEl.value);
      rowsEl.innerHTML = out.html;
      countEl.textContent = out.count === page.utilities.length ? num(out.count) + ' classes' : num(out.count) + ' of ' + num(page.utilities.length);
    }
    filterEl.addEventListener('input', draw);
    draw();
    if (focusClass) focusRow(document.getElementById('u-' + focusClass));
  }

  /** Highlights a table row and scrolls its table (not the page) to it. */
  function focusRow(row) {
    if (!row) return;
    row.classList.add('is-target');
    var scroller = row.closest('.d-table-scroll');
    if (!scroller) return;
    var offset = row.getBoundingClientRect().top - scroller.getBoundingClientRect().top;
    scroller.scrollTop += offset - scroller.clientHeight / 2 + row.offsetHeight / 2;
  }

  // Copy buttons, palette chips (delegated)
  main.addEventListener('click', function (e) {
    var chip = e.target.closest('.d-chip');
    if (chip) {
      var name = chip.getAttribute('data-color');
      document.getElementById('d-chip-detail').innerHTML = colorDetail(name);
      copy('bg-' + name);
      return;
    }
    var codeBtn = e.target.closest('[data-copy-code]');
    if (codeBtn) {
      var code = codeBtn.parentNode.querySelector('code');
      copy(code ? code.textContent : '');
      return;
    }
    var btn = e.target.closest('[data-copy]');
    if (btn && btn.tagName !== 'A') copy(btn.getAttribute('data-copy'));
  });

  // ------------------------------------------------------------------ search box

  var input = document.getElementById('d-search-input');
  var resultsEl = document.getElementById('d-search-results');
  var current = [];
  var selected = -1;

  function drawResults() {
    var q = input.value;
    current = search(q, 12);
    selected = current.length ? 0 : -1;
    if (!q.trim()) { hideResults(); return; }
    var total = search(q).length;
    resultsEl.innerHTML = current.length ? current.map(function (r, i) {
      return '<button type="button" class="d-result" role="option" data-i="' + i + '" aria-selected="' + (i === selected) + '">' +
        '<span class="d-result-kind">' + esc(r.kind) + '</span>' +
        (r.hex ? '<span class="d-swatch" style="width:18px;height:18px;border-radius:4px"><span style="background:' + esc(r.hex) + '"></span></span>' : '') +
        '<span class="d-result-main"><span class="d-result-title">' + esc(r.title) + '</span><span class="d-result-sub">' + esc(r.sub) + '</span></span></button>';
    }).join('') + (total > current.length ? '<div class="d-result-foot">Shift + Enter to see all ' + num(total) + ' results</div>' : '')
      : '<div class="d-result-empty">No matches. New syntax like <code class="d-inline-code">w-[250px]</code> is compiled on demand.</div>';
    resultsEl.hidden = false;
    input.setAttribute('aria-expanded', 'true');
  }
  function hideResults() {
    resultsEl.hidden = true;
    input.setAttribute('aria-expanded', 'false');
  }
  function go(i) {
    var r = current[i];
    if (!r) return;
    hideResults();
    input.blur();
    location.hash = r.href;
  }
  function select(i) {
    selected = i;
    Array.prototype.forEach.call(resultsEl.querySelectorAll('.d-result'), function (el, idx) {
      el.setAttribute('aria-selected', String(idx === i));
      if (idx === i) el.scrollIntoView({ block: 'nearest' });
    });
  }

  input.addEventListener('input', drawResults);
  input.addEventListener('focus', function () { if (input.value.trim()) drawResults(); });
  input.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowDown') { e.preventDefault(); if (current.length) select((selected + 1) % current.length); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); if (current.length) select((selected - 1 + current.length) % current.length); }
    else if (e.key === 'Enter') {
      // Enter opens the highlighted result; Shift+Enter (or no results) opens the full results page.
      e.preventDefault();
      if (e.shiftKey || selected === -1) {
        if (!input.value.trim()) return;
        hideResults();
        input.blur();
        location.hash = '#/search?q=' + encodeURIComponent(input.value);
      } else {
        go(selected);
      }
    } else if (e.key === 'Escape') { hideResults(); input.blur(); }
  });
  resultsEl.addEventListener('mousedown', function (e) {
    var el = e.target.closest('.d-result');
    if (el) { e.preventDefault(); go(Number(el.getAttribute('data-i'))); }
  });
  document.addEventListener('click', function (e) {
    if (!e.target.closest('.d-search')) hideResults();
  });
  document.addEventListener('keydown', function (e) {
    var tag = (document.activeElement && document.activeElement.tagName) || '';
    if (e.key === '/' && tag !== 'INPUT' && tag !== 'TEXTAREA') { e.preventDefault(); input.focus(); input.select(); }
  });

  // ------------------------------------------------------------------ boot

  renderSidebar();
  window.addEventListener('hashchange', route);
  route();
})();
